@startuml

class Airplane {
  + model : string
  + price : double
  + deliveryDate : date
}

class Acquisition {
  + price : double
}

class Contract {
  + deliveryConditions : string
  + legalAspects : string
}

class AirlineCompany {
  + name : string
}

class Employee {
  + name : string
}

class Salesperson extends Employee {}

Contract "1" *-- "1..*" Acquisition : consists of
Acquisition "1" -- "1" Airplane : involves
Contract "0..*" -- "1" Salesperson : managed by
Contract "*" -- "1" AirlineCompany : signed by
AirlineCompany "0..1" -- "0..*" AirlineCompany : mother-daughter relationship

@enduml

